+
+describe('DatastoreAccessInformation', () => {
+    const iamMock = mockClient(IAMClient);
+
+    beforeEach(() => {
+        iamMock.reset();
+        process.env.DB_MEASUREMENT_BUCKET_NAME = 'usage-ingestion';
+        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'usage-dlq';
+    });
+
+    it('defaults S3 configuration and provisions a unique scoped role', async () => {
+        iamMock.on(CreateRoleCommand).resolves({ Role: { Arn: 'arn:aws:iam::123:role/generated-role' } as any });
+        iamMock.on(PutRolePolicyCommand).resolves({});
+        const configuration = new DatastoreAccessInformation({
+            accountId: '111122223333',
+            businessID: 'business-1',
+        } as DatastoreAccessInformation);
